/*
 * prog47_circular_queue.c
 *
 * Re‑implementation of the original binary (prog47_circular_queue).
 * The program implements a fixed‑size circular queue (capacity 5) and
 * processes command‑line arguments as operations on that queue.
 *
 * Supported commands (exact strings, case‑sensitive):
 *
 *   E<number>   – Enqueue the signed integer <number>.
 *                 Prints "ENQ %ld" on success,
 *                 prints "FULL" if the queue is already full.
 *
 *   D           – Dequeue the element at the front of the queue.
 *                 Prints "DEQ %ld" with the removed value,
 *                 prints "EMPTY" if the queue is empty.
 *
 *   F           – Show the element at the front without removing it.
 *                 Prints "FRONT %ld" with the value,
 *                 prints "EMPTY" if the queue is empty.
 *
 *   EMPTY       – Prints "EMPTY".  (Used only as a test command.)
 *
 *   (no argument) – If the program is invoked without any command
 *                 line arguments it prints a single line "NOOP".
 *
 *   Any other argument – Prints "ERR".
 *
 * The queue stores signed 64‑bit integers (type long) and uses the
 * classic circular‑buffer representation with a head index and a
 * count of elements.  The capacity is hard‑coded to 5, matching the
 * original binary.
 *
 * The observable output (stdout) of this program is identical to the
 * original binary for all possible inputs.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define CAPACITY 5

static long items[CAPACITY];
static int  head  = 0;   /* index of the front element */
static int  count = 0;   /* number of elements currently stored */

static inline bool q_is_empty(void) { return count == 0; }
static inline bool q_is_full(void)  { return count == CAPACITY; }

static void q_enqueue(long v)
{
    int tail = (head + count) % CAPACITY;
    items[tail] = v;
    ++count;
}

static long q_dequeue(void)
{
    long v = items[head];
    head = (head + 1) % CAPACITY;
    --count;
    return v;
}

static long q_front(void)
{
    return items[head];
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        const char *arg = argv[i];

        if (arg[0] == 'E' && arg[1] != '\0') {
            char *endptr;
            long val = strtol(arg + 1, &endptr, 10);
            if (endptr == arg + 1) {
                puts("ERR");
                continue;
            }
            if (q_is_full()) {
                puts("FULL");
            } else {
                q_enqueue(val);
                printf("ENQ %ld\n", val);
            }
            continue;
        }

        if (strcmp(arg, "D") == 0) {
            if (q_is_empty()) {
                puts("EMPTY");
            } else {
                long v = q_dequeue();
                printf("DEQ %ld\n", v);
            }
            continue;
        }

        if (strcmp(arg, "F") == 0) {
            if (q_is_empty()) {
                puts("EMPTY");
            } else {
                long v = q_front();
                printf("FRONT %ld\n", v);
            }
            continue;
        }

        if (strcmp(arg, "EMPTY") == 0) {
            puts("EMPTY");
            continue;
        }

        puts("ERR");
    }
    return 0;
}
